16	/**
17	 * Returns the home directory.
18	 * If GEMINI_CLI_HOME environment variable is set, it returns its value.
19	 * Otherwise, it returns the user's home directory.
20	 */
21	export function homedir(): string {
22	  const envHome = process.env['GEMINI_CLI_HOME'];
23	  if (envHome) {
24	    return envHome;
25	  }
26	  return os.homedir();
27	}
