36	/**
37	 * Replaces the home directory with a tilde.
38	 * @param path - The path to tildeify.
39	 * @returns The tildeified path.
40	 */
41	export function tildeifyPath(path: string): string {
42	  const homeDir = homedir();
43	  if (path.startsWith(homeDir)) {
44	    return path.replace(homeDir, '~');
45	  }
46	  return path;
47	}
