13	describe('planUtils', () => {
14	  let tempRootDir: string;
15	  let plansDir: string;
16	
17	  beforeEach(() => {
18	    tempRootDir = fs.realpathSync(
19	      fs.mkdtempSync(path.join(os.tmpdir(), 'planUtils-test-')),
20	    );
21	    const plansDirRaw = path.join(tempRootDir, 'plans');
22	    fs.mkdirSync(plansDirRaw, { recursive: true });
23	    plansDir = fs.realpathSync(plansDirRaw);
24	  });
25	
26	  afterEach(() => {
27	    if (fs.existsSync(tempRootDir)) {
28	      fs.rmSync(tempRootDir, { recursive: true, force: true });
29	    }
30	  });
31	
32	  describe('validatePlanPath', () => {
33	    it('should return null for a valid path within plans directory', async () => {
34	      const planPath = path.join('plans', 'test.md');
35	      const fullPath = path.join(tempRootDir, planPath);
36	      fs.writeFileSync(fullPath, '# My Plan');
37	
38	      const result = await validatePlanPath(planPath, plansDir);
39	      expect(result).toBeNull();
40	    });
41	
42	    it('should return error for non-existent file', async () => {
43	      const planPath = path.join('plans', 'ghost.md');
44	      const result = await validatePlanPath(planPath, plansDir);
45	      expect(result).toContain('Plan file does not exist');
46	    });
47	
48	    it('should detect path traversal via symbolic links', async () => {
49	      const maliciousPath = path.join('plans', 'malicious.md');
50	      const fullMaliciousPath = path.join(tempRootDir, maliciousPath);
51	      const outsideFile = path.join(tempRootDir, 'outside.txt');
52	      fs.writeFileSync(outsideFile, 'secret content');
53	
54	      // Create a symbolic link pointing outside the plans directory
55	      fs.symlinkSync(outsideFile, fullMaliciousPath);
56	
57	      const result = await validatePlanPath(maliciousPath, plansDir);
58	      expect(result).toContain('Access denied');
59	    });
60	  });
61	
62	  describe('validatePlanContent', () => {
63	    it('should return null for non-empty content', async () => {
64	      const planPath = path.join(plansDir, 'full.md');
65	      fs.writeFileSync(planPath, 'some content');
66	      const result = await validatePlanContent(planPath);
67	      expect(result).toBeNull();
68	    });
69	
70	    it('should return error for empty content', async () => {
71	      const planPath = path.join(plansDir, 'empty.md');
72	      fs.writeFileSync(planPath, '   ');
73	      const result = await validatePlanContent(planPath);
74	      expect(result).toContain('Plan file is empty');
75	    });
76	
77	    it('should return error for unreadable file', async () => {
78	      const planPath = path.join(plansDir, 'ghost.md');
79	      const result = await validatePlanContent(planPath);
80	      // Since isEmpty treats unreadable files as empty (defensive),
81	      // we expect the "Plan file is empty" message.
82	      expect(result).toContain('Plan file is empty');
83	    });
84	  });
85	});
