31	export interface ExitPlanModeParams {
32	  plan_filename: string;
33	}
34	
35	export class ExitPlanModeTool extends BaseDeclarativeTool<
36	  ExitPlanModeParams,
37	  ToolResult
38	> {
39	  static readonly Name = EXIT_PLAN_MODE_TOOL_NAME;
40	
41	  constructor(
42	    private config: Config,
43	    messageBus: MessageBus,
44	  ) {
45	    const definition = getExitPlanModeDefinition();
46	    super(
47	      ExitPlanModeTool.Name,
48	      'Exit Plan Mode',
49	      definition.base.description!,
50	      Kind.Plan,
51	      definition.base.parametersJsonSchema,
52	      messageBus,
53	    );
54	  }
55	
56	  protected override validateToolParamValues(
57	    params: ExitPlanModeParams,
58	  ): string | null {
59	    if (!params.plan_filename || params.plan_filename.trim() === '') {
60	      return 'plan_filename is required.';
61	    }
62	
63	    const safeFilename = path.basename(params.plan_filename);
64	    const plansDir = resolveToRealPath(this.config.storage.getPlansDir());
65	    const resolvedPath = path.join(
66	      this.config.storage.getPlansDir(),
67	      safeFilename,
68	    );
69	
70	    const realPath = resolveToRealPath(resolvedPath);
71	
72	    if (!isSubpath(plansDir, realPath)) {
73	      return `Access denied: plan path (${resolvedPath}) must be within the designated plans directory (${plansDir}).`;
74	    }
75	
76	    return null;
77	  }
78	
79	  protected createInvocation(
80	    params: ExitPlanModeParams,
81	    messageBus: MessageBus,
82	    toolName: string,
83	    toolDisplayName: string,
84	  ): ExitPlanModeInvocation {
85	    return new ExitPlanModeInvocation(
86	      params,
87	      messageBus,
88	      toolName,
89	      toolDisplayName,
90	      this.config,
91	    );
92	  }
93	
94	  override getSchema(modelId?: string) {
95	    return resolveToolDeclaration(getExitPlanModeDefinition(), modelId);
96	  }
97	}
