99	export class ExitPlanModeInvocation extends BaseToolInvocation<
100	  ExitPlanModeParams,
101	  ToolResult
102	> {
103	  private confirmationOutcome: ToolConfirmationOutcome | null = null;
104	  private approvalPayload: ToolExitPlanModeConfirmationPayload | null = null;
105	  private planValidationError: string | null = null;
106	
107	  constructor(
108	    params: ExitPlanModeParams,
109	    messageBus: MessageBus,
110	    toolName: string,
111	    toolDisplayName: string,
112	    private config: Config,
113	  ) {
114	    super(params, messageBus, toolName, toolDisplayName);
115	  }
116	
117	  override async shouldConfirmExecute(
118	    abortSignal: AbortSignal,
119	  ): Promise<ToolExitPlanModeConfirmationDetails | false> {
120	    const resolvedPlanPath = this.getResolvedPlanPath();
121	
122	    const pathError = await validatePlanPath(
123	      this.params.plan_filename,
