}", "newString": "/**
 * Resolves an untrusted plan file path to an absolute path and validates that
 * it is contained within the authorized plans directory.
 *
 * The agent may provide the path in a few different forms, so we try them in
 * order of preference:
 *   1. An absolute path (used as-is when inside the plans directory).
 *   2. A path relative to the project root (as displayed in the system prompt).
 *   3. A path relative to the plans directory itself.
 *
 * Nested directories are preserved so plans can be organized into
 * subdirectories within the plans directory.
 *
 * @param planPath The untrusted path to the plan file.
 * @param plansDir The authorized project plans directory.
 * @param projectRoot The absolute path to the project root directory.
 * @returns The resolved absolute path to the plan file.
 * @throws If the resolved path escapes the plans directory.
 */
export function resolveAndValidatePlanPath(
  planPath: string,
  plansDir: string,
  projectRoot: string,
): string {
  const trimmedPath = planPath.trim();
  if (!trimmedPath) {
    throw new Error('Plan file path must be non-empty.');
  }

  // 1. Handle case where agent provided an absolute path.
  if (path.isAbsolute(trimmedPath)) {
    if (isSubpath(resolveToRealPath(plansDir), resolveToRealPath(trimmedPath))) {
      return trimmedPath;
    }
  }

  // 2. Handle case where agent provided a path relative to the project root.
  const resolvedFromProjectRoot = path.resolve(projectRoot, trimmedPath);
  if (
    isSubpath(
      resolveToRealPath(plansDir),
      resolveToRealPath(resolvedFromProjectRoot),
    )
  ) {
    return resolvedFromProjectRoot;
  }

  // 3. Handle default case where agent provided a path relative to the plans
  // directory.
  const resolvedPath = path.resolve(plansDir, trimmedPath);
  const realPath = resolveToRealPath(resolvedPath);
  const realPlansDir = resolveToRealPath(plansDir);

  if (!isSubpath(realPlansDir, realPath)) {
    throw new Error(PlanErrorMessages.PATH_ACCESS_DENIED(trimmedPath, plansDir));
  }

  return resolvedPath;
}

/**
 * Validates a plan file path for safety (traversal) and existence.
 * @param planPath The untrusted path to the plan file.
 * @param plansDir The authorized project plans directory.
 * @param projectRoot The absolute path to the project root directory.
 * @returns An error message if validation fails, or null if successful.
 */
export async function validatePlanPath(
  planPath: string,
  plansDir: string,
  projectRoot: string,
): Promise<string | null> {
  try {
    const resolvedPath = resolveAndValidatePlanPath(
      planPath,
      plansDir,
      projectRoot,
    );
    if (!(await fileExists(resolvedPath))) {
      return PlanErrorMessages.FILE_NOT_FOUND(planPath);
    }
    return null;
  } catch {
    return PlanErrorMessages.PATH_ACCESS_DENIED(
      planPath,
      resolveToRealPath(plansDir),
    );
  }
